  0:  { strong: [1, 7, 10], medium: [6, 17, 21] },
  1:  { strong: [2, 3, 7], medium: [4, 6, 15] },
  2:  { strong: [9, 18, 5], medium: [11, 12, 17] },
  3:  { strong: [4, 6, 19], medium: [1, 14, 21] },
