  5:  { strong: [2, 6, 11], medium: [4, 9, 20] },
  6:  { strong: [7, 14, 15], medium: [3, 8, 19] },
  7:  { strong: [8, 10, 11], medium: [1, 4, 16] },
  8:  { strong: [9, 14, 19], medium: [6, 7, 15] },
  9:  { strong: [10, 17, 18], medium: [2, 12, 20] },
  10: { strong: [11, 13, 16], medium: [0, 17, 21] },
  11: { strong: [12, 13, 20], medium: [4, 5, 14] },
