const CARD_NARRATIVE = {
  0:  { leave: "まだ何者でもない自由さが、選択肢を閉じないまま次へ踏み出し", arrive: "未知を恐れず、意味が生まれる前の余白へ戻っていく" },
  1:  { leave: "自分の手で状況を動かそうとする意志が形になり", arrive: "手元の資源を使い、可能性を具体的な行為へ変えていく" },
  2:  { leave: "言葉になる前の直感を抱えたまま静かに進み", arrive: "表面ではなく、まだ見えていない内側の声へ注意を向ける" },
  3:  { leave: "育て、受け入れ、増やしてきたものが次の局面を呼び", arrive: "足りないものを埋めるより、すでにある豊かさを育て直す" },
  4:  { leave: "秩序を作り、境界を定めた力が次の状態を押し出し", arrive: "曖昧だったものに線を引き、責任ある形へ整えていく" },
  5:  { leave: "受け継いだ価値や教えを土台にしながら進み", arrive: "一人では得られない知恵や、共有された基準へ立ち返る" },
  6:  { leave: "心が何かを選び取ったことで流れが変わり", arrive: "正しさよりも、自分が本当に結びたいものを選び直す" },
  7:  { leave: "迷いを抱えたままでも前進する勢いが生まれ", arrive: "方向を決め、ばらばらな力を一つの進路へ束ねていく" },
  8:  { leave: "力で押さえつけず、扱い方を覚えた強さが残り", arrive: "衝動を消すのではなく、壊さずに扱える強さへ変えていく" },
  9:  { leave: "外の声から距離を取り、内側で確かめたものを携え", arrive: "答えを急がず、自分だけが見える小さな灯りを頼りに進む" },
  10: { leave: "偶然に見えた出来事が流れとして回り始め", arrive: "止められない変化の中で、自分がどこに乗るかを見極める" },
  11: { leave: "感情から少し離れて釣り合いを測った結果が残り", arrive: "都合ではなく、何が公平かを静かに見直していく" },
  12: { leave: "動かないことを選んだ時間が視点を反転させ", arrive: "進むことをやめることで、今まで見えなかった意味を拾う" },
  13: { leave: "終わらせたことで空いた場所に、新しい流れが入り込み", arrive: "戻れない変化を受け入れ、次の形のために古いものを閉じる" },
  14: { leave: "極端を避け、異なるものを混ぜ合わせた感覚が残り", arrive: "急がず少しずつ調整し、無理のない中間点を探していく" },
  15: { leave: "欲望や執着との結びつきがはっきり見えたことで", arrive: "自分を縛っているものが、本当に外からの鎖なのかを確かめる" },
  16: { leave: "保っていた構造が崩れ、隠れていた事実が露出し", arrive: "壊れたものを元通りにせず、露わになった真実から立て直す" },
  17: { leave: "崩れた後にも残った小さな希望を手にして進み", arrive: "結果を急がず、遠くても消えない目印を信じ直していく" },
  18: { leave: "確信できないまま揺れる感覚を抱えて歩き", arrive: "不安と直感が混じる夜の中で、見えていないものを想像する" },
  19: { leave: "曖昧さが晴れ、隠れていたものが明るみに出たことで", arrive: "複雑に考えすぎず、今ここにある明快さを受け取っていく" },
  20: { leave: "過去を振り返ることで、もう一度呼ばれているものに気づき", arrive: "終わったと思っていたものを別の視点から呼び戻し、判断する" },
  21: { leave: "一つの巡りが完成し、全体像を見渡せる地点に立ち", arrive: "完成を終点にせず、得たものを携えて次の循環へ移っていく" },
};

const ORIGIN_TEXT = "何も受け継いでいない、最初の一枚。遷移の起点であり、まだどこにも属していない。この札自体には意味がない――次に何が来るかによって、初めて役割が決まる。";


const BRIDGES = [
  "ここでは、前の札を否定して次へ進むのではなく、その経験が次の札の見え方を変えています。",
  "変化の核心は、前の状態が消えることではなく、その名残が次の選択の条件になる点にあります。",
  "二枚の間には断絶よりも受け渡しがあります。前の札で得たものが、次の札では別の形で試されます。",
  "この遷移は結論ではなく途中経過です。前の札で生まれた偏りが、次の札で新しい意味を持ち始めます。",
];

function connectionLevel(fromId, toId) {
  const profile = TRANSITION_PROFILE[fromId] || { strong: [], medium: [] };
  if (fromId === toId) return "self";
  if (profile.strong.includes(toId)) return "strong";
  if (profile.medium.includes(toId)) return "medium";
  return "weak";
}

function buildTransitionText(fromCard, toCard) {
  const from = CARD_NARRATIVE[fromCard.id];
  const to = CARD_NARRATIVE[toCard.id];
  const level = connectionLevel(fromCard.id, toCard.id);
  const bridge = BRIDGES[(fromCard.id * 7 + toCard.id * 11) % BRIDGES.length];

  if (level === "self") {
    return `${fromCard.name}から再び${toCard.name}へ。同じ主題が繰り返されたのは、まだ次へ移るより、今いる場所をもう一度見直す必要があるからです。${to.arrive}。同じ札でも二度目は反復ではなく、最初には見えなかった部分を確かめる時間になります。`;
  }

  const tone = level === "strong"
    ? "流れは強くつながっています。"
    : level === "medium"
      ? "流れには自然な連続性があります。"
      : "少し意外な方向への遷移です。";

  return `${fromCard.name}から${toCard.name}へ。${from.leave}、${to.arrive}。${tone}${bridge}`;
}

const TRANSITION_TEXT = Object.fromEntries(
  MAJOR_ARCANA.flatMap((fromCard) =>
    MAJOR_ARCANA.map((toCard) => [`${fromCard.id}-${toCard.id}`, buildTransitionText(fromCard, toCard)])
  )
);

function getTransitionWeights(fromId) {
  const profile = TRANSITION_PROFILE[fromId] || { strong: [], medium: [] };
  return MAJOR_ARCANA.map((card) => {
    if (card.id === fromId) return 0.35;
    if (profile.strong.includes(card.id)) return 5;
    if (profile.medium.includes(card.id)) return 2.5;
    return 1;
  });
}

function pickWeightedNext(fromCard) {
  const weights = getTransitionWeights(fromCard.id);
  const total = weights.reduce((sum, w) => sum + w, 0);
  let r = Math.random() * total;
  for (let i = 0; i < MAJOR_ARCANA.length; i += 1) {
    r -= weights[i];
    if (r <= 0) return MAJOR_ARCANA[i];
  }
  return MAJOR_ARCANA[MAJOR_ARCANA.length - 1];
}

let history = [];
let interpretation = "";
let fadeKey = 0;

const historyEl = document.getElementById('history');
const stageEl = document.getElementById('stage');
const interpretationEl = document.getElementById('interpretation');
const drawBtn = document.getElementById('drawBtn');
const resetBtn = document.getElementById('resetBtn');

function escapeHtml(s) {
  return String(s).replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
}

function render() {
  const current = history[history.length - 1] || null;
  const previous = history.length > 1 ? history[history.length - 2] : null;

  if (history.length) {
    historyEl.hidden = false;
    historyEl.innerHTML = history.map((c, i) => {
      const active = i === history.length - 1;
      const arrow = i < history.length - 1 ? '<span class="history-arrow">→</span>' : '';
      return `<span class="history-item"><span class="history-chip${active ? ' active' : ''}">${escapeHtml(c.name)}</span>${arrow}</span>`;
    }).join('');
  } else {
    historyEl.hidden = true;
    historyEl.innerHTML = '';
  }

  stageEl.classList.remove('fade');
  void stageEl.offsetWidth;
  stageEl.classList.add('fade');

  if (current) {
    stageEl.innerHTML = `
      <div class="card-frame"><img src="${current.image}" alt="${escapeHtml(current.num)} ${escapeHtml(current.name)}"></div>
      ${previous ? `<div class="transition-label">直前：${escapeHtml(previous.name)} → 今回：${escapeHtml(current.name)}</div>` : ''}
    `;
  } else {
    stageEl.innerHTML = `<div class="empty-state">まだ何も引かれていない。<br>最初の一枚を引いてみてください。</div>`;
  }

  interpretationEl.textContent = interpretation;
  drawBtn.textContent = history.length === 0 ? '最初の一枚を引く' : '次の一枚を引く';
  resetBtn.hidden = history.length === 0;
}

function draw() {
  if (history.length === 0) {
    history = [MAJOR_ARCANA[0]];
    interpretation = ORIGIN_TEXT;
    fadeKey += 1;
    render();
    return;
  }
  const prevCard = history[history.length - 1];
  const nextCard = pickWeightedNext(prevCard);
  history = [...history, nextCard];
  interpretation = TRANSITION_TEXT[`${prevCard.id}-${nextCard.id}`] || buildTransitionText(prevCard, nextCard);
  fadeKey += 1;
  render();
}

function reset() {
  history = [];
  interpretation = '';
  fadeKey += 1;
  render();
}

drawBtn.addEventListener('click', draw);
resetBtn.addEventListener('click', reset);
render();
